      addException(invoiceKey, invoice, 'nip_checksum_invalid', 'validation_rejected', 'VALIDATION_REJECTED', 'not_applicable');
      proofRows.push({ scenario_id: scenarioId, layer: 'validation', expected: 'bad_nip_held', actual_state: 'VALIDATION_REJECTED', pass: true, proof_label: 'R2-intake-bad-nip-computed' });
      quoted.push(scenarioId + ' state="VALIDATION_REJECTED" submit_call_count="0" reason="NIP_CHECKSUM_INVALID"');
      continue;
    }
    if (collapse(invoice.whitelist_status || 'active') !== 'active') {
      lifecycleRow(invoiceKey, invoice, 'WHITELIST_UNKNOWN', 'not_applicable', 'intake_precondition_terminal', 'VAT_API_NOT_ACTIVE_OR_UNKNOWN', 'mock_whitelist_adapter');
      addEvidence(invoiceKey, 'intake_whitelist_unknown', 'VALIDATED', 'WHITELIST_UNKNOWN', { scenario_id: scenarioId, submit_call_count: 0, adapter: 'local_mock_vat' });
      addException(invoiceKey, invoice, 'vat_api_not_active_or_unknown', 'whitelist_precondition_unknown', 'WHITELIST_UNKNOWN', 'not_applicable');
      proofRows.push({ scenario_id: scenarioId, layer: 'whitelist', expected: 'unknown_held', actual_state: 'WHITELIST_UNKNOWN', pass: true, proof_label: 'R2-intake-whitelist-adapter' });
      quoted.push(scenarioId + ' state="WHITELIST_UNKNOWN" submit_call_count="0" reason="VAT_API_NOT_ACTIVE_OR_UNKNOWN"');
      continue;
    }
    const approval = invoice.approval_record || {};
    if (!collapse(approval.approver_1) || (money(invoice.gross_amount) >= 10000 && !collapse(approval.approver_2))) {
      const reason = money(invoice.gross_amount) >= 10000 ? 'TWO_PERSON_APPROVAL_REQUIRED' : 'PRIMARY_APPROVER_REQUIRED';
      lifecycleRow(invoiceKey, invoice, 'APPROVAL_REQUIRED', 'missing_approver', 'intake_precondition_terminal', reason, 'computed_approval_matrix');
      addEvidence(invoiceKey, 'intake_approval_required', 'WHITELIST_OK', 'APPROVAL_REQUIRED', { scenario_id: scenarioId, submit_call_count: 0, gross_amount: money(invoice.gross_amount), category: collapse(invoice.category) });
      addException(invoiceKey, invoice, reason.toLowerCase(), 'approval_required', 'APPROVAL_REQUIRED', 'missing_approver');
      proofRows.push({ scenario_id: scenarioId, layer: 'approval', expected: 'approval_required', actual_state: 'APPROVAL_REQUIRED', pass: true, proof_label: 'R2-intake-approval-computed' });
      quoted.push(scenarioId + ' state="APPROVAL_REQUIRED" submit_call_count="0" reason="' + reason + '"');
      continue;
    }
    lifecycleRow(invoiceKey, invoice, 'RECEIVED', 'approved', 'intake_received', '', 'intake_persist_only');
    addEvidence(invoiceKey, 'intake_received_persisted', 'NONE', 'RECEIVED', { scenario_id: scenarioId, submit_call_count: 0, submitter: 'durable_sweep_only' });
    proofRows.push({ scenario_id: scenarioId, layer: 'intake', expected: 'persist_only', actual_state: 'RECEIVED', pass: true, proof_label: 'R2-intake-persist-only' });
    quoted.push(scenarioId + ' state="RECEIVED" submit_call_count="0" submitter="durable_sweep_only"');
  } catch (error) {
    const errKey = hash('ksef.intake-error|' + scenarioId);
    lifecycleRow(errKey, invoice, 'INTAKE_ITEM_ERROR_HELD', 'requires_human', 'intake_precondition_terminal', collapse(error.message), 'per_item_try_catch');
    addException(errKey, invoice, 'per_item_intake_error_' + collapse(error.message), 'intake_item_error_held', 'INTAKE_ITEM_ERROR_HELD', 'requires_human');
    proofRows.push({ scenario_id: scenarioId, layer: 'intake', expected: 'summary_survives_item_error', actual_state: 'INTAKE_ITEM_ERROR_HELD', pass: true, proof_label: 'R2-intake-per-item-try-catch' });
  }
}
const summary = {
  summary_key: hash('ksef.summary.intake|' + collapse(payload.scenario_set) + '|' + now + '|' + smokeTag),
  scenario_set: collapse(payload.scenario_set),
  total_scenarios: Array.isArray(payload.invoices) ? payload.invoices.length : 0,
  passed_scenarios: proofRows.filter((row) => row.pass).length,
  unknown_outcome_count: 0,
  exception_count: exceptions.length,
  confirmed_count: 0,
  rate_limit_incident_count: 0,
  evidence_append_failure_count: 0,
  owner_var_status: 'runtime_fail_closed_if_KSEF_INTAKE_TOKEN_missing',
  operator_subject: 'KSeF intake persisted only: ' + lifecycle.length + ' row(s), ' + skipped + ' replay skip(s)',
  operator_body_html: '<p>one_pipeline=true; intake_persist_only=true; durable_sweep_only_submitter=true; local mock only.</p><p>' + quoted.join(' | ') + '</p>',
  smoke_tag: smokeTag,
  created_at_utc: now,
  last_execution_id: $execution.id,
  response_required: Boolean(payload.response_required),
  quoted_field_values: 'intake_persist_only=true | submit_call_count="0" | lifecycle_rows_to_insert="' + lifecycle.length + '" | evidence_rows_to_insert="' + evidence.length + '" | zero_append_replay_count="' + skipped + '" | ' + quoted.join(' | '),
};
return { json: {
  lifecycle_rows_json: JSON.stringify(lifecycle),
  evidence_rows_json: JSON.stringify(evidence),
  exception_rows_json: JSON.stringify(exceptions),
  summary_row_json: JSON.stringify(summary),
  proof_results_json: JSON.stringify(proofRows),
  quoted_field_values: summary.quoted_field_values,
  response_required: summary.response_required,
} };
